"""Clean up the contacts export before it goes into the mailing tool."""
import csv
from datetime import date


def read_contacts(path):
    """Read the exported CSV (name, email, phone, updated) into dicts."""
    with open(path, newline="", encoding="utf-8") as fh:
        return list(csv.DictReader(fh))


def tidy(row):
    """Trim stray spaces and lowercase the email."""
    return {
        "name": row["name"].strip(),
        "email": row["email"].strip().lower(),
        "phone": row["phone"].strip(),
        "updated": row["updated"].strip(),
    }


def clean(rows):
    """The clean-up step run on every export.

    One row per email address. When an address appears more than once, the
    row with the latest 'updated' date is kept; older rows are stale.
    """
    latest = {}
    for row in rows:
        contact = tidy(row)
        seen = latest.get(contact["email"])
        newer = seen is None or (date.fromisoformat(contact["updated"])
                                 > date.fromisoformat(seen["updated"]))
        if newer:
            latest[contact["email"]] = contact
    return list(latest.values())

