"""Load bank transactions into our budget format."""
from datetime import datetime


def parse_date(text):
    """Turn the date column into a date.

    Handles 2024-03-15 style dates, and the new account's slash dates,
    which are day/month/year.
    """
    text = text.strip()
    if "/" in text:
        return datetime.strptime(text, "%d/%m/%Y").date()
    return datetime.strptime(text, "%Y-%m-%d").date()


def parse_amount(text):
    """'1,234.50' -> 1234.5; a trailing '-' means money going out."""
    text = text.strip().replace(",", "")
    if text.endswith("-"):
        return -float(text[:-1])
    return float(text)


def parse_row(row):
    """One row of the bank's CSV export."""
    return {
        "date": parse_date(row["Date"]),
        "description": row["Description"].strip(),
        "amount": parse_amount(row["Amount"]),
    }

