"""Recipe cards for the cafe kitchen."""
import math


def parse_ingredient(line):
    """'200 g flour' -> {'qty': 200.0, 'unit': 'g', 'name': 'flour'}.

    Things counted rather than measured use the unit 'x', as in '3 x eggs'.
    """
    qty, unit, name = line.split(maxsplit=2)
    return {"qty": float(qty), "unit": unit, "name": name}


def format_ingredient(ing):
    qty = ing["qty"]
    text = str(int(qty)) if qty == int(qty) else f"{qty:g}"
    return f"{text} {ing['unit']} {ing['name']}"


def load_card(text):
    """First line is 'serves N'; every other line is an ingredient."""
    lines = [l.strip() for l in text.strip().splitlines() if l.strip()]
    serves = int(lines[0].split()[1])
    return {"serves": serves,
            "ingredients": [parse_ingredient(l) for l in lines[1:]]}


def card_text(card):
    lines = [f"serves {card['serves']}"]
    lines += [format_ingredient(i) for i in card["ingredients"]]
    return "\n".join(lines)


def scale(card, serves):
    """A copy of the card for a different number of servings.

    Measured ingredients scale in proportion. Counted ones (unit 'x') are
    rounded up to a whole number: you can't use part of an egg.
    """
    factor = serves / card["serves"]
    ingredients = []
    for ing in card["ingredients"]:
        qty = ing["qty"] * factor
        if ing["unit"] == "x":
            qty = float(math.ceil(round(qty, 9)))
        ingredients.append({**ing, "qty": qty})
    return {"serves": serves, "ingredients": ingredients}

