"""User preferences for the notes app."""
import json

DEFAULTS = {
    "theme": "light",
    "font_size": 14,
    "language": "en",
    "autosave_minutes": 5,
    "show_line_numbers": False,
}


def load(path):
    """Saved preferences laid over the defaults."""
    try:
        with open(path, encoding="utf-8") as fh:
            saved = json.load(fh)
    except FileNotFoundError:
        saved = {}
    return {**DEFAULTS, **saved}


def save(path, prefs):
    with open(path, "w", encoding="utf-8") as fh:
        json.dump(prefs, fh, indent=2)


KEEP_ON_RESET = ("language",)


def reset(prefs):
    """Preferences after the user presses 'Reset to defaults'.

    Everything goes back to DEFAULTS except the language the person chose.
    """
    out = dict(DEFAULTS)
    for key in KEEP_ON_RESET:
        if key in prefs:
            out[key] = prefs[key]
    return out

