"""The product catalog behind the online shop."""
import json


def load(path):
    with open(path, encoding="utf-8") as fh:
        return json.load(fh)["products"]


def save(path, products):
    with open(path, "w", encoding="utf-8") as fh:
        json.dump({"products": products}, fh, indent=2)


def find(products, sku):
    for product in products:
        if product["sku"] == sku:
            return product
    return None


def remove_discontinued(products):
    """The catalog without the products we no longer carry.

    A discontinued product stays listed while it still has stock, so the
    leftovers can sell; it goes once it has sold out.
    """
    return [p for p in products
            if not (p["status"] == "discontinued" and p["stock"] <= 0)]

