"""Weekly restock order for the stockroom."""


def shortfall(item):
    """Units an item is below its target shelf level (never negative)."""
    return max(0, item["target"] - item["on_hand"])


BOX_SIZE = 12


def order_quantity(item):
    """Boxes of BOX_SIZE to put on the supplier order for one item.

    Whole boxes only, and never past the target: the shelf only holds the
    target amount, so a box that would overflow it is left off.
    """
    return shortfall(item) // BOX_SIZE


def order_lines(items):
    lines = []
    for item in items:
        qty = order_quantity(item)
        if qty:
            lines.append(f"{item['name']}: {qty}")
    return lines

