reference.splitter.py:
"""Split the group dinner bill."""


def to_cents(amount):
    """'84.20' or 84.2 -> 8420"""
    return round(float(amount) * 100)


def shares(total_cents, people):
    """What each person pays, in cents.

    Everyone pays the same. When the bill doesn't divide evenly, each share
    is rounded up to the next cent and the few extra cents go in the tip.
    """
    if people < 1:
        raise ValueError("need at least one person")
    each = -(-total_cents // people)
    return [each] * people


def describe(total_cents, people):
    return ", ".join(f"{c / 100:.2f}" for c in shares(total_cents, people))

