"""Read KEY=VALUE settings files for the deploy scripts."""


def parse(text):
    """Turn the file contents into a dict.

    Blank lines, and lines whose first non-space character is #, are skipped.
    A # further along a line is part of the value.
    """
    settings = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        key, value = stripped.split("=", 1)
        settings[key.strip()] = value.strip()
    return settings


def load(path):
    with open(path, encoding="utf-8") as fh:
        return parse(fh.read())

reference.stats.py:
"""Small statistics helpers for the lab's plate-reader exports."""


def mean(values):
    values = list(values)
    if not values:
        raise ValueError("no values")
    return sum(values) / len(values)


def spread(values):
    values = list(values)
    if not values:
        raise ValueError("no values")
    return max(values) - min(values)


def median(values):
    """Middle value of the readings; with an even count, the mean of the two
    middle ones."""
    values = sorted(values)
    if not values:
        raise ValueError("no values")
    mid = len(values) // 2
    if len(values) % 2:
        return values[mid]
    return (values[mid - 1] + values[mid]) / 2

