"""Build the static blog from markdown posts."""
import re


def read_post(text):
    """Split the '---' front matter (key: value lines) from the body."""
    _, front, body = text.split("---", 2)
    meta = {}
    for line in front.strip().splitlines():
        key, value = line.split(":", 1)
        meta[key.strip()] = value.strip()
    return meta, body.strip()


def slugify(title):
    """URL part for a post title: lowercase letters, digits and single hyphens."""
    text = title.lower().replace(" ", "-")
    text = re.sub(r"[^a-z0-9-]", "", text)
    text = re.sub(r"-{2,}", "-", text)
    return text.strip("-")


def output_path(meta):
    return f"posts/{slugify(meta['title'])}.html"

