"""Member report for the climbing gym's front desk.

Member records have: name, plan, joined (a date) and last_visit (a date).
Every date in this report is shown with fmt_date(), e.g. '05 Mar 2024', so
the desk staff see one style throughout.
"""

HEADER = ["Name", "Plan", "Joined", "Last visit"]


def fmt_date(d):
    return d.strftime("%d %b %Y")


def member_row(m):
    """One row of the report as a list of strings."""
    return [m["name"], m["plan"], fmt_date(m["joined"]),
            fmt_date(m["last_visit"])]


def build(members):
    rows = [HEADER] + [member_row(m) for m in members]
    return "\n".join(" | ".join(row) for row in rows)

