    """The last n entries."""
    return by_newest(entries)[:n]


def bills(entries):
    """Recurring bills only."""
    return by_newest(e for e in entries if e.get("recurring"))


def in_category(entries, category):
    """Every entry in one category, in date order (newest first)."""
    return by_newest(e for e in entries if e["category"] == category)

