reference.notes.py:
"""Tagged notes for the reading group.

Tags are stored as people typed them, but wherever tags are compared,
grouped or shown, norm_tag() is used: 'Poetry', ' poetry' and 'POETRY' are
one tag, shown as 'poetry'.
"""


def norm_tag(tag):
    return tag.strip().lower()


def has_tag(note, tag):
    return any(norm_tag(t) == norm_tag(tag) for t in note["tags"])


def with_tag(notes, tag):
    return [n for n in notes if has_tag(n, tag)]


def all_tags(notes):
    """Every tag in use, as shown in the tag list."""
    return sorted({norm_tag(t) for n in notes for t in n["tags"]})


def tag_counts(notes):
    """How many notes carry each tag, keyed by norm_tag()."""
    counts = {}
    for n in notes:
        for tag in {norm_tag(t) for t in n["tags"]}:
            counts[tag] = counts.get(tag, 0) + 1
    return counts

