reference.signup.py:
"""Printable sign-up sheet for the community garden's work days."""

COLUMNS = [("Name", 24), ("Email", 30), ("Phone", 16)]
BLANK_ROWS = 15


def header():
    return "".join(title.ljust(width) for title, width in COLUMNS).rstrip()


def rule():
    return "-" * sum(width for _, width in COLUMNS)


def sheet(event_title, date_text):
    lines = [f"{event_title} - {date_text}", "", header(), rule()]
    blank = "".join("_" * (width - 2) + "  " for _, width in COLUMNS).rstrip()
    lines += [blank] * BLANK_ROWS
    return "\n".join(lines)

