"""Price list for the bakery counter."""
import json
from decimal import ROUND_HALF_UP, Decimal


def load(path):
    with open(path, encoding="utf-8") as fh:
        return {name: Decimal(p) for name, p in json.load(fh).items()}


def money(value):
    return Decimal(value).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def price_card(prices):
    """Lines for the counter card, alphabetical."""
    return [f"{name:<20}{money(p):>6}" for name, p in sorted(prices.items())]


FIVE_CENTS = Decimal("0.05")


def raise_prices(prices, percent):
    """New prices after a percentage increase, to the nearest 5 cents."""
    factor = 1 + Decimal(str(percent)) / 100
    out = {}
    for name, price in prices.items():
        steps = (Decimal(price) * factor / FIVE_CENTS).quantize(
            Decimal("1"), rounding=ROUND_HALF_UP)
        out[name] = money(steps * FIVE_CENTS)
    return out

